import { exec } from 'node:child_process';

export function makeThumb(file: Upload) {
  const cmd = `convert ${file.originalname} -resize 200x200 out/${file.id}.png`;
  return new Promise((ok, fail) =>
    exec(cmd, (err) => (err ? fail(err) : ok(undefined))));
}

